def esc(s): return str(s).replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')
def localized(s,lang):
 # Explicit localization for common profile prose. Tool names/commands remain unchanged.
 if lang=='pt':
  mp={'No extra runtime is required.':'Nenhum runtime adicional é necessário.','A JDK is required, not only a JRE. Prefer a currently supported LTS JDK for QA tooling unless the project specifies another version.':'É necessário um JDK, não apenas um JRE. Prefira um JDK LTS suportado para ferramentas de QA, salvo exigência diferente do projeto.','Node.js includes npm. Prefer an LTS release for stable automation environments.':'Node.js inclui npm. Prefira uma versão LTS para ambientes de automação estáveis.','Node.js/npm are required. Android testing also needs Java JDK, Android SDK/platform-tools and a configured device/emulator. iOS automation requires macOS and Xcode.':'Node.js/npm são obrigatórios. Testes Android também exigem Java JDK, Android SDK/platform-tools e dispositivo/emulador configurado. Automação iOS exige macOS e Xcode.','Python and pip must be installed. Use a virtual environment to isolate project dependencies.':'Python e pip devem estar instalados. Use ambiente virtual para isolar as dependências do projeto.','Node.js LTS and npm are required.':'Node.js LTS e npm são obrigatórios.'}
  return mp.get(s,s)
 if lang=='es':
  mp={'No extra runtime is required.':'No se requiere un runtime adicional.','Node.js LTS and npm are required.':'Se requieren Node.js LTS y npm.','Python and pip must be installed. Use a virtual environment to isolate project dependencies.':'Python y pip deben estar instalados. Use un entorno virtual para aislar las dependencias del proyecto.'}
  return mp.get(s,s)
 return s


def command_explain(cmd,lang):
 c=cmd.lower().strip()
 msg={
 'version':{'pt':'Confirma que o executável está acessível e informa a versão. Se não houver resposta válida, corrija instalação/PATH antes de continuar.','en':'Confirms the executable is available and reports its version. If it fails, fix installation/PATH before continuing.','es':'Confirma que el ejecutable está disponible e informa su versión. Si falla, corrija instalación/PATH antes de continuar.'},
 'install':{'pt':'Instala o componente/dependência indicado. Aguarde a conclusão e confirme uma mensagem de sucesso.','en':'Installs the specified component/dependency. Wait for completion and confirm a success message.','es':'Instala el componente/dependencia indicado. Espere a que termine y confirme un mensaje de éxito.'},
 'list':{'pt':'Lista os componentes já instalados; use a saída para confirmar que o item esperado está presente.','en':'Lists already installed components; use the output to confirm the expected item is present.','es':'Lista los componentes ya instalados; use la salida para confirmar que el elemento esperado está presente.'},
 'venv':{'pt':'Cria um ambiente virtual isolado; ao final deve existir a pasta .venv.','en':'Creates an isolated virtual environment; a .venv directory should exist afterward.','es':'Crea un entorno virtual aislado; al finalizar debe existir la carpeta .venv.'},
 'activate':{'pt':'Ativa o ambiente virtual; normalmente o prompt passa a exibir (.venv).','en':'Activates the virtual environment; the prompt normally shows (.venv).','es':'Activa el entorno virtual; normalmente el prompt muestra (.venv).'},
 'run':{'pt':'Executa a validação funcional inicial. Leia a saída completa e confirme que não há falhas.','en':'Runs the initial functional validation. Read the complete output and confirm there are no failures.','es':'Ejecuta la validación funcional inicial. Lea toda la salida y confirme que no existen fallos.'},
 'generic':{'pt':'Execute no terminal indicado, leia toda a saída e resolva qualquer erro antes do próximo passo.','en':'Run it in the indicated terminal, read the complete output and resolve any error before the next step.','es':'Ejecútelo en el terminal indicado, lea toda la salida y resuelva cualquier error antes del siguiente paso.'}}
 if 'driver list' in c or c.startswith('npm list') or c.endswith('config --list'): typ='list'
 elif 'activate' in c or 'source .venv' in c: typ='activate'
 elif 'venv' in c: typ='venv'
 elif '--version' in c or ' -v' in c or c.endswith(' version'): typ='version'
 elif ' install ' in (' '+c+' ') or c.startswith('npm install') or c.startswith('pip install'): typ='install'
 elif any(x in c for x in [' run ',' test','hello-world','archetype:generate']): typ='run'
 else: typ='generic'
 return msg[typ][lang]

