def action_text(x,lang,title):
 if lang=='en': return x
 # Commands remain unchanged. Narrative first-use actions are localized without leaking English.
 low=x.lower()
 iscmd=any(tok in low for tok in [' --',' -m ','npm ','npx ','python','java ','git ','docker ','kubectl ','terraform','mvn ','gradle','jmeter','k6 ','locust','allure ','adb ','code ','prometheus','\\scripts\\','source .venv','appium']) and not low.startswith(('open ','launch ','use ','create ','configure ','perform '))
 if iscmd: return x
 if lang=='pt':
  if x.startswith('Open http'): return 'Abra '+x.split('Open ',1)[1].split(' after ',1)[0]+' no navegador depois que o serviço estiver em execução.'
  if x.startswith('Launch '): return 'Abra '+title+' e conclua a validação inicial descrita neste manual.'
  return 'Execute a etapa de primeiro uso indicada para '+title+' e confirme visualmente que terminou sem erros.'
 if x.startswith('Open http'): return 'Abra '+x.split('Open ',1)[1].split(' after ',1)[0]+' en el navegador después de que el servicio esté en ejecución.'
 if x.startswith('Launch '): return 'Abra '+title+' y complete la validación inicial descrita en este manual.'
 return 'Realice la etapa de primer uso indicada para '+title+' y confirme visualmente que finalizó sin errores.'

def os_text(k,lang,field,title):
 if lang=='en': return P[k][field]
 idx={'win':0,'mac':1,'linux':2}[field]
 if k in OS_LOCAL: return OS_LOCAL[k][lang][idx]
 osn={'win':'Windows','mac':'macOS','linux':'Linux'}[field]
 return (f'Instale {title} pelo método oficial específico para {osn}, valide os pré-requisitos e execute os comandos desta seção antes de avançar.' if lang=='pt' else f'Instale {title} mediante el método oficial específico para {osn}, valide los prerrequisitos y ejecute los comandos de esta sección antes de continuar.')

def pre_text(k,lang,title):
 # Equal-depth localized prerequisite block; OS-specific details are immediately below.
 p=P[k]['pre']
 if lang=='en': return p
 deps=[]
 for token,labelpt,labeles in [('node','Node.js/npm','Node.js/npm'),('jdk','JDK/Java','JDK/Java'),('python','Python/pip','Python/pip'),('android','Android SDK/platform-tools','Android SDK/platform-tools'),('docker','Docker','Docker')]:
  if token in p.lower(): deps.append(labelpt if lang=='pt' else labeles)
 base=', '.join(dict.fromkeys(deps))
 if lang=='pt': return ('Confirme permissões de instalação e acesso à internet.' + (f' Pré-requisitos específicos: {base}.' if base else '') + ' Use somente versões suportadas pela documentação oficial da ferramenta.')
 return ('Confirme permisos de instalación y acceso a Internet.' + (f' Prerrequisitos específicos: {base}.' if base else '') + ' Use únicamente versiones compatibles según la documentación oficial de la herramienta.')

def expect_text(k,lang,title):
 if lang=='en': return P[k]['expect']
 # Keep result specific by describing the actual first-use command/action.
 first=P[k]['first'][0] if P[k]['first'] else ''
 if lang=='pt': return f'{title} deve concluir a validação sem erros. Na etapa de primeiro uso ({action_text(first,lang,title)}), confirme o comportamento esperado e ausência de falhas de instalação, PATH ou dependências.'
 return f'{title} debe completar la validación sin errores. En el primer uso ({action_text(first,lang,title)}), confirme el comportamiento esperado y la ausencia de fallos de instalación, PATH o dependencias.'

def is_command_item(x):
 low=x.lower().strip()
 return not low.startswith(('open ','launch ','use ','create ','configure ','perform ')) and (any(tok in low for tok in [' --',' -m ','npm ','npx ','python','java ','git ','docker ','kubectl ','terraform','mvn ','gradle','jmeter','k6 ','locust','allure ','adb ','code ','prometheus','appium','\\scripts\\','source .venv']) or ('\\' in x and ' ' not in x))

def add_steps(story, items, lang, title):
 for i,x in enumerate(items,1):
  story.append(Paragraph(f'<b>{i}.</b> {esc(action_text(x,lang,title))}',B))

